<script setup>
import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue'
import { api } from '../services/api'
import { useRoute } from 'vue-router'
const route = useRoute()
const photos=ref([]), categories=ref([]), search=ref(typeof route.query.search === 'string' ? route.query.search : ''), category=ref(''), page=ref(1), last=ref(1), total=ref(0), selected=ref(-1), loading=ref(true), error=ref('')
const slidePhotos=ref([]), slideIndex=ref(0)
const currentSlide=computed(()=>slidePhotos.value[slideIndex.value] || null)
const previousSlide=computed(()=>slidePhotos.value.length > 1 ? slidePhotos.value[(slideIndex.value + slidePhotos.value.length - 1) % slidePhotos.value.length] : null)
const nextSlide=computed(()=>slidePhotos.value.length > 2 ? slidePhotos.value[(slideIndex.value + 1) % slidePhotos.value.length] : null)
let slideTimer
const formatDate = date => date ? new Intl.DateTimeFormat('id-ID', { day:'numeric', month:'short', year:'numeric', timeZone:'UTC' }).format(new Date(date)) : null
const closeButton=ref(null); let timer, previousFocus, requestId=0
async function load(){ const id=++requestId; loading.value=true; error.value=''; try{const result=await api.get('/photos',{params:{search:search.value,category:category.value,page:page.value}}); if(id!==requestId)return; photos.value=result.data.data;last.value=result.data.last_page;total.value=result.data.total}catch{if(id===requestId)error.value='Foto belum dapat dimuat. Periksa koneksi ke server.'}finally{if(id===requestId)loading.value=false} }
function openPhoto(index){previousFocus=document.activeElement;selected.value=index;document.body.style.overflow='hidden';nextTick(()=>closeButton.value?.focus())}
function closePhoto(){selected.value=-1;document.body.style.overflow='';nextTick(()=>previousFocus?.focus())}
function move(delta){selected.value=(selected.value+delta+photos.value.length)%photos.value.length}
function keys(e){if(selected.value<0)return;if(e.key==='Escape')closePhoto();else if(e.key==='ArrowRight')move(1);else if(e.key==='ArrowLeft')move(-1)}
watch(() => route.query.search, value => { search.value = typeof value === 'string' ? value : ''; category.value = '' })
watch([search,category],()=>{clearTimeout(timer);page.value=1;timer=setTimeout(load,250)})
function changePage(value){page.value=value;load();window.scrollTo({top:0,behavior:'smooth'})}
onMounted(()=>{load();api.get('/photos').then(r=>{slidePhotos.value=r.data.data}).catch(()=>{});slideTimer=window.setInterval(()=>{if(!document.hidden && slidePhotos.value.length>1)slideIndex.value=(slideIndex.value+1)%slidePhotos.value.length},5000);api.get('/categories').then(r=>categories.value=r.data).catch(()=>{});window.addEventListener('keydown',keys)})
onUnmounted(()=>{clearTimeout(timer);clearInterval(slideTimer);window.removeEventListener('keydown',keys);document.body.style.overflow=''})
</script>
<template>
 <main class="gallery-page wrap">
  <section class="jakarta-intro" aria-labelledby="gallery-title">
   <div class="intro-copy"><div class="intro-kicker"><span></span> DOKUMENTASI WILAYAH</div><h1 id="gallery-title">Kelurahan<br><em>Grogol Selatan.</em></h1><p>Grogol Selatan merupakan kelurahan di Kecamatan Kebayoran Lama, Kota Administrasi Jakarta Selatan. Galeri ini memuat dokumentasi kegiatan dan kehidupan masyarakat di wilayah tersebut.</p><div class="intro-facts"><span v-if="!loading && !error"><strong>{{total}}</strong> foto tersedia</span><span>Kebayoran Lama</span><span>Unduh foto asli</span></div></div>
   <div class="intro-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-panel"><div class="art-panel-top"><span><i></i> KOLEKSI FOTO</span><span>JAKARTA / ID</span></div><div class="art-image" v-if="currentSlide"><Transition name="slide-fade"><img :key="currentSlide.id" :src="currentSlide.thumbnail_url" alt=""></Transition><div class="art-image-caption"><span>ARSIP VISUAL</span><strong>{{currentSlide.album?.title}}</strong></div></div><div class="art-image art-empty" v-else><span>JAKARTA PHOTO GALLERY</span></div><div class="art-panel-bottom"><span>FOTO &amp; DOKUMENTASI</span><span>{{String(slideIndex+1).padStart(2,'0')}} — {{String(slidePhotos.length).padStart(2,'0')}}</span></div></div><div class="art-mini art-mini-one" v-if="previousSlide"><img :src="previousSlide.thumbnail_url" alt=""></div><div class="art-mini art-mini-two" v-if="nextSlide"><img :src="nextSlide.thumbnail_url" alt=""></div><svg class="monas-ornament" viewBox="0 0 120 230" fill="none"><path d="M60 7c-10 16 6 17-1 33 13-7 12-22 1-33Z" fill="#ffca72"/><path d="M55 42h10l4 119H51L55 42Z" fill="#f3eee6"/><path d="M35 157h50l-5 13H40l-5-13Zm7 13h36v13H42v-13ZM27 183h66v11H27v-11Zm-7 11h80v10H20v-10Z" fill="#f3eee6"/><path d="M10 210h100" stroke="#ffca72" stroke-width="2"/></svg><div class="art-label">MONAS <span> / JAKARTA</span></div></div>
  </section>
  <div class="balang-border" aria-hidden="true"></div>
  <section class="collection-heading" id="koleksi"><div><div class="intro-kicker"><span></span> KOLEKSI PUBLIK</div><h2>Galeri Foto</h2><p>Temukan foto berdasarkan nama album atau kategori.</p></div><span v-if="!loading && !error" class="collection-total">{{total}} foto tersedia</span></section>
  <div class="gallery-toolbar"><div class="gallery-filters"><label class="search-field"><span aria-hidden="true">⌕</span><input v-model="search" aria-label="Cari foto atau album" placeholder="Cari foto atau album..."></label><select v-model="category" aria-label="Filter kategori"><option value="">Semua kategori</option><option v-for="c in categories" :key="c.id" :value="c.slug">{{c.name}}</option></select></div><span v-if="!loading && !error" class="gallery-hint">{{ total }} foto ditemukan</span></div>
  <div v-if="loading" class="notice">Memuat foto...</div><div v-else-if="error" class="notice">{{error}} <button @click="load">Coba lagi</button></div><div v-else-if="!photos.length" class="notice">Tidak ada foto yang cocok. Coba kata kunci atau kategori lain.</div>
  <div v-else class="gallery-grid"><button v-for="(p,i) in photos" :key="p.id" class="gallery-tile" @click="openPhoto(i)" :aria-label="'Perbesar '+p.original_filename"><img :src="p.thumbnail_url" :alt="p.original_filename" loading="lazy"><span class="tile-overlay"><span><small>{{p.album?.category?.name || 'Dokumentasi'}} <template v-if="p.album?.event_date"> · {{formatDate(p.album.event_date)}}</template></small><strong>{{p.album?.title}}</strong><span class="tile-filename">{{p.original_filename}}</span></span><b aria-hidden="true">↗</b></span></button></div>
  <div v-if="last>1" class="pagination"><button :disabled="page<=1" @click="changePage(page-1)">← Sebelumnya</button><span>{{page}} / {{last}}</span><button :disabled="page>=last" @click="changePage(page+1)">Berikutnya →</button></div>
  <div v-if="selected>=0" class="lightbox gallery-modal" role="dialog" aria-modal="true" aria-label="Pratinjau foto" @click.self="closePhoto"><button ref="closeButton" class="close" aria-label="Tutup" @click="closePhoto">×</button><button class="modal-arrow" aria-label="Foto sebelumnya" @click="move(-1)">←</button><figure><img :src="photos[selected].thumbnail_url" :alt="photos[selected].original_filename"><figcaption><span><strong>{{photos[selected].album?.title}}</strong><br>{{photos[selected].original_filename}}<template v-if="photos[selected].width && photos[selected].height"> · {{photos[selected].width}} × {{photos[selected].height}} px</template><template v-if="photos[selected].album?.event_date"> · {{formatDate(photos[selected].album.event_date)}}</template><template v-if="photos[selected].album?.location"> · {{photos[selected].album.location}}</template></span><a class="download-link" :href="api.defaults.baseURL+'/photos/'+photos[selected].id+'/download'">↓ &nbsp; Unduh foto</a></figcaption></figure><button class="modal-arrow" aria-label="Foto berikutnya" @click="move(1)">→</button></div>
 </main>
</template>
